import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { useState } from "react";
import {
  faLocationDot,
  faIndianRupeeSign,
  faBuilding,
  faShieldHalved,
  faHardHat,
  faCalendarDays,
  faSliders
} from "@fortawesome/free-solid-svg-icons";

const PROPERTY_TYPE_OPTIONS = [
  "All Types",
  "Residential",
  {
    group: "Residential",
    options: [
      "Apartment",
      "Independent",
      "Farm House",
      "Villa",
      "Penthouse",
      "Studio House",
      "Car Parking (R)",
      "Rooftop Leasing for Solar",
      "Event Spaces (Short Time)",
      "PG Service/Co-Living"
    ]
  },
  "Commercial",
  {
    group: "Commercial",
    options: [
      "Office Space",
      "Showroom",
      "Shop",
      "IT Park (SEZ)",
      "Warehouse",
      "Co-working Spaces",
      "Car Parking (C)"
    ]
  },
  "Land",
  {
    group: "Land",
    options: [
      "Residential",
      "Commercial",
      "Industrial",
      "Agricultural",
      "Farm House",
      "Urban Farming"
    ]
  }
];

const FILTERS = [
  {
    key: "location",
    icon: faLocationDot,
    label: "Location",
    value: "Hyderabad",
    options: ["All Locations", "Hyderabad", "Bengaluru", "Chennai", "Pune"]
  },
  {
    key: "budget",
    icon: faIndianRupeeSign,
    label: "Budget",
    value: "Any Budget",
    options: ["Any Budget", "Under ₹50L", "₹50L - ₹1Cr", "₹1Cr - ₹2Cr", "Above ₹2Cr"]
  },
  {
    key: "propertyType",
    icon: faBuilding,
    label: "Property Type",
    value: "All Types",
    options: PROPERTY_TYPE_OPTIONS
  },
  {
    key: "approval",
    icon: faShieldHalved,
    label: "Approval",
    value: "Any Approval",
    options: ["Any Approval", "RERA Approved", "HMDA Approved", "DTCP Approved", "Bank Approved"]
  },
  {
    key: "builderName",
    icon: faHardHat,
    label: "Builder",
    value: "All Builders",
    options: ["All Builders", "Aparna", "My Home", "Prestige", "Brigade"]
  },
  {
    key: "possession",
    icon: faCalendarDays,
    label: "Possession",
    value: "Any Time",
    options: ["Any Time", "Ready to Move", "Within 6 Months", "Within 1 Year", "Under Construction"]
  }
];
const DEFAULT_FILTER_VALUES = Object.fromEntries(FILTERS.map((filter) => [filter.key, filter.value]));

function FilterBar({ values = DEFAULT_FILTER_VALUES, onChange, onApply }) {
  const [isApplying, setIsApplying] = useState(false);

  const handleApply = async () => {
    setIsApplying(true);
    try {
      await onApply?.(values);
    } finally {
      setIsApplying(false);
    }
  };

  return <form className="vd-filter-wrap" onSubmit={(event) => {
    event.preventDefault();
    handleApply();
  }}>
      {FILTERS.map((f) => <div key={f.label} className="vd-filter-item">
          <div className="vd-fl-label">
            <FontAwesomeIcon icon={f.icon} className="fa-icon" />
            {f.label}
          </div>
          <div className="vd-fl-val">
            <select
    className="vd-fl-select"
    value={values[f.key] ?? f.value}
    onChange={(event) => onChange?.({ ...values, [f.key]: event.target.value })}
    aria-label={f.label}
  >
              {f.options.map((option, index) => {
                if (typeof option === "string") {
                  return <option key={option} value={option}>
                      {option}
                    </option>;
                }

                return <optgroup key={`${option.group}-${index}`} label={option.group}>
                    {option.options.map((groupOption) => <option key={`${option.group}-${groupOption}`} value={groupOption}>
                        {groupOption}
                      </option>)}
                  </optgroup>;
              })}
            </select>
          </div>
        </div>)}
      <button className="vd-filter-more-btn" type="submit" disabled={isApplying}>
        <FontAwesomeIcon icon={faSliders} />
        {isApplying ? "Applying..." : "Apply Filters"}
      </button>
    </form>;
}
export {
  FilterBar as default,
  DEFAULT_FILTER_VALUES
};
