function MapPane({ projects }) {
  const mappedProjects = projects.map((project) => ({
    project,
    coordinates: getProjectCoordinates(project.projectData)
  })).filter(({ coordinates }) => coordinates);

  const latitudes = mappedProjects.map(({ coordinates }) => coordinates.latitude);
  const longitudes = mappedProjects.map(({ coordinates }) => coordinates.longitude);
  const latitude = (Math.min(...latitudes) + Math.max(...latitudes)) / 2;
  const longitude = (Math.min(...longitudes) + Math.max(...longitudes)) / 2;
  const latitudePadding = Math.max((Math.max(...latitudes) - Math.min(...latitudes)) * 0.15, 0.015);
  const longitudePadding = Math.max((Math.max(...longitudes) - Math.min(...longitudes)) * 0.15, 0.02);
  const south = Math.max(-90, Math.min(...latitudes) - latitudePadding);
  const north = Math.min(90, Math.max(...latitudes) + latitudePadding);
  const west = Math.max(-180, Math.min(...longitudes) - longitudePadding);
  const east = Math.min(180, Math.max(...longitudes) + longitudePadding);
  const mapUrl = `https://www.openstreetmap.org/export/embed.html?bbox=${west}%2C${south}%2C${east}%2C${north}&layer=mapnik`;
  const directionsUrl = `https://www.google.com/maps?q=${latitude},${longitude}`;
  const northMercatorY = toWebMercatorY(north);
  const southMercatorY = toWebMercatorY(south);

  return <div className="vd-map-wrap">
      <iframe
        className="vd-map-grid"
        title={`Map showing ${mappedProjects.length} project locations`}
        src={mapUrl}
        loading="lazy"
        referrerPolicy="no-referrer"
      />
      <div className="vd-map-markers" aria-label="Project locations">
        {mappedProjects.map(({ project, coordinates }) => {
          const x = ((coordinates.longitude - west) / (east - west)) * 100;
          const y = ((northMercatorY - toWebMercatorY(coordinates.latitude)) / (northMercatorY - southMercatorY)) * 100;
          const projectMapUrl = `https://www.google.com/maps?q=${coordinates.latitude},${coordinates.longitude}`;

          return <a
            key={project.id}
            className="vd-map-marker"
            href={projectMapUrl}
            target="_blank"
            rel="noopener noreferrer"
            style={{ left: `${x}%`, top: `${y}%` }}
            title={`${project.name} - Open in Google Maps`}
            aria-label={`${project.name} location, open in Google Maps`}
          >
            <FontAwesomeIcon icon={faLocationDot} aria-hidden="true" />
          </a>;
        })}
      </div>
      <div className="vd-map-status" role="status">Showing {mappedProjects.length} project locations</div>
      <a className="vd-map-project-link" href={directionsUrl} target="_blank" rel="noopener noreferrer">
        Open area in Google Maps
      </a>
    </div>;
}
const formatPriceValue = (value) => {
  if (value === null || value === undefined || value === "") {
    return "N/A";
  }

  if (typeof value === "number" && Number.isFinite(value)) {
    return `\u20B9 ${new Intl.NumberFormat("en-IN", {
      maximumFractionDigits: 0
    }).format(value)}`;
  }

  const valueText = String(value).trim();
  return valueText.startsWith("\u20B9") ? valueText : `\u20B9 ${valueText}`;
};

const formatProjectDate = (value) => {
  if (value === null || value === undefined || value === "") {
    return "N/A";
  }

  const raw = String(value).trim();

  if (!raw || /^(n\/a|null|undefined)$/i.test(raw)) {
    return "N/A";
  }

  const numericValue = Number(raw);
  const parsed = Number.isFinite(numericValue) && numericValue >= 20000 && numericValue <= 100000
    ? new Date(Date.UTC(1899, 11, 30) + Math.floor(numericValue) * 86400000)
    : new Date(raw);

  if (Number.isNaN(parsed.getTime())) {
    return raw;
  }

  return parsed.toLocaleDateString("en-IN", {
    day: "2-digit",
    month: "short",
    year: "numeric"
  });
};

const normalizeApprovals = (approvals) => {
  if (Array.isArray(approvals)) {
    return Array.from(new Set(approvals.flatMap((approval) => normalizeApprovals(approval))));
  }

  if (typeof approvals === "string") {
    const normalized = approvals.replace(/\bRERAHMDA\b/gi, "RERA, HMDA");
    return Array.from(new Set(normalized.split(/[,|]/).map((entry) => entry.trim()).filter(Boolean)));
  }

  return [];
};

const isEnabled = (value) => {
  if (typeof value === "boolean") {
    return value;
  }

  if (typeof value === "number") {
    return value === 1;
  }

  return typeof value === "string" && /^(true|1|yes|y)$/i.test(value.trim());
};

const deriveStatus = (project) => {
  const dbStatus = String(project?.ProjectStatus || "").trim();

  if (isEnabled(project?.IsNewLaunch)) {
    return { status: dbStatus || "New Launch", statusClass: "new-launch" };
  }

  if (isEnabled(project?.IsReadyToMove)) {
    return { status: dbStatus || "Ready to Move", statusClass: "ready" };
  }

  if (isEnabled(project?.IsUnderConstruction)) {
    return { status: dbStatus || "Under Construction", statusClass: "construction" };
  }

  const status = dbStatus || "Project";
  const statusClass = STATUS_CLASS_MAP[String(status).toLowerCase()] || "construction";
  return { status, statusClass };
};

const getPlanApprovalNumber = (project) => {
  const rawValue = findDatabaseField(project, ["PlanApprovalNumber", "PlanApprovalNo", "PlanNo", "ApprovalNumber", "LpApprovalNumber", "LpNumber", "LPNumber"]);
  return String(rawValue).trim();
};

const normalizeFieldKey = (value) => String(value || "").toLowerCase().replace(/[^a-z0-9]/g, "");

const formatDatabaseValue = (value) => {
  if (value === null || value === undefined || value === "") {
    return "N/A";
  }

  if (Array.isArray(value)) {
    return value.map((entry) => formatDatabaseValue(entry)).filter((entry) => entry !== "N/A").join(", ") || "N/A";
  }

  if (typeof value === "object") {
    return JSON.stringify(value);
  }

  return String(value).trim() || "N/A";
};

const findDatabaseEntry = (source, targetKeys) => {
  if (!source || typeof source !== "object") {
    return undefined;
  }

  const normalizedTargets = targetKeys.map(normalizeFieldKey);
  const stack = [source];
  const seen = new Set();

  while (stack.length > 0) {
    const current = stack.pop();

    if (!current || typeof current !== "object" || seen.has(current)) {
      continue;
    }

    seen.add(current);

    for (const [key, value] of Object.entries(current)) {
      const normalizedKey = normalizeFieldKey(key);

      if (normalizedTargets.includes(normalizedKey) && value !== null && value !== undefined && String(value).trim() !== "") {
        return { key, value };
      }

      if (value && typeof value === "object") {
        stack.push(value);
      }
    }
  }

  return undefined;
};

const findDatabaseValue = (source, targetKeys) => findDatabaseEntry(source, targetKeys)?.value;

const getProjectCoordinates = (source) => {
  const latitudeValue = findDatabaseValue(source, ["Latitude", "Lat"]);
  const longitudeValue = findDatabaseValue(source, ["Longitude", "Long", "Lng"]);
  if (latitudeValue === undefined || latitudeValue === null || String(latitudeValue).trim() === ""
    || longitudeValue === undefined || longitudeValue === null || String(longitudeValue).trim() === "") {
    return null;
  }

  const latitude = Number(latitudeValue);
  const longitude = Number(longitudeValue);
  if (!Number.isFinite(latitude) || !Number.isFinite(longitude)
    || latitude < -90 || latitude > 90 || longitude < -180 || longitude > 180) {
    return null;
  }

  return { latitude, longitude };
};

const toWebMercatorY = (latitude) => {
  const radians = Math.max(-85.05112878, Math.min(85.05112878, latitude)) * Math.PI / 180;
  return Math.log(Math.tan(Math.PI / 4 + radians / 2));
};

const findDatabaseField = (source, targetKeys) => formatDatabaseValue(findDatabaseValue(source, targetKeys));

const formatBooleanField = (source, targetKeys) => {
  const value = findDatabaseValue(source, targetKeys);
  if (value === undefined) {
    return "N/A";
  }

  if (typeof value === "boolean" || typeof value === "number" || typeof value === "string") {
    const normalized = String(value).trim().toLowerCase();
    if (["true", "1", "yes", "y"].includes(normalized)) {
      return "Yes";
    }
    if (["false", "0", "no", "n"].includes(normalized)) {
      return "No";
    }
  }

  return formatDatabaseValue(value);
};

const formatProjectAddress = (value) => {
  const segments = Array.isArray(value) ? value : value && typeof value === "object" ? Object.values(value) : String(value || "").split(",");
  const uniqueSegments = new Map();

  segments.forEach((segment) => {
    const normalized = formatDatabaseValue(segment);
    if (normalized !== "N/A" && !/^(null|undefined)$/i.test(normalized)) {
      uniqueSegments.set(normalized.toLowerCase(), normalized);
    }
  });

  return Array.from(uniqueSegments.values()).join(", ");
};

const mapProjectToCard = (project, index) => {
  const { status, statusClass } = deriveStatus(project);
  const approvals = normalizeApprovals(project?.Approvals);
  const planApprovalNumber = getPlanApprovalNumber(project);
  const projectType = project?.ProjectType || project?.Type || "N/A";
  const proposedCompletionDate = formatProjectDate(findDatabaseValue(project, ["ProposedDateOfCompletion", "ProposedCompletionDate", "ProposedCompletion", "ExpectedCompletionDate"]));
  const reraRegistrationNumber = findDatabaseField(project, ["RERANo", "ReraNumber", "ReraNo", "ReraId", "ReraRegistrationNumber", "RegistrationNumber"]);
  const createdDate = formatProjectDate(findDatabaseValue(project, ["CreatedDate", "CreatedOn", "CreateDate"]));
  const updatedDate = formatProjectDate(findDatabaseValue(project, ["UpdatedDate", "UpdatedOn", "ModifiedDate", "ModifiedOn"]));
  const rawAddress = findDatabaseValue(project, ["FullAddress", "Address", "ProjectAddress"]);
  const composedAddress = rawAddress ?? [
    findDatabaseValue(project, ["AddressLine1"]),
    findDatabaseValue(project, ["AddressLine2"]),
    findDatabaseValue(project, ["Street", "Locality"]),
    findDatabaseValue(project, ["Village", "VillageName"]),
    findDatabaseValue(project, ["Mandal", "Taluk"]),
    findDatabaseValue(project, ["District"]),
    findDatabaseValue(project, ["State"]),
    findDatabaseValue(project, ["Pincode", "PinCode", "PostalCode"])
  ].filter((value) => value !== undefined);

  return {
    id: project?.ProjectId || project?.Id || `${project?.ProjectName || "project"}-${index}`,
    status,
    statusClass,
    img: project?.ImageUrl || project?.ThumbnailUrl || FALLBACK_IMAGE,
    name: project?.ProjectName || "Unnamed Project",
    builder: project?.BuilderName || "Builder details unavailable",
    location: formatProjectAddress(composedAddress) || "Location unavailable",
    projectType,
    proposedCompletionDate,
    reraRegistrationNumber,
    planApprovalNumber: planApprovalNumber || "N/A",
    createdDate,
    updatedDate,
    reraValidity: formatBooleanField(project, ["ReraValidity", "IsReraValid", "ReraValid", "ReraValidTill", "IsReraVerified", "ReraStatus"]),
    projectData: project,
    tags: approvals.map((approval, approvalIndex) => ({
      key: `${approval.toLowerCase().replace(/\s+/g, "-")}-${approvalIndex}`,
      label: approval,
      tooltip: planApprovalNumber ? `Plan Approval Number: ${planApprovalNumber}` : "Plan Approval Number: N/A"
    })),
    aiLabel: project?.AIInsight || "No AI insight available",
    aiDetail: ""
  };
};

